 cat=decodeURIComponent(cat);const all=DB.models.filter(x=>x.e3_category==cat);const mfs=[...new Set(all.map(x=>x.manufacturer_id))].sort((a,b)=>(M[a]?.short||a).localeCompare(M[b]?.short||b));
