 <select onchange="XF.rf=this.value;drawX('${encodeURIComponent(cat)}')"><option value="">Любой статус РФ</option>${Object.keys(RFS).map(s=>`<option ${XF.rf==s?'selected':''}>${s}</option>`).join("")}</select>
 
