function drawX(c){const cat=decodeURIComponent(c);const q=XF.q.toLowerCase();const L=DB.models.filter(x=>x.e3_category==cat&&(!XF.mf||x.manufacturer_id==XF.mf)&&(!XF.aud||x.audience==XF.aud)&&(!XF.rf||(M[x.manufacturer_id]?.rf_status||"неизвестно")==XF.rf)&&(!XF.maxh||(x.min_height_cm==null?XF.unk:x.min_height_cm<=+XF.maxh))&&(!XF.minpph||(pphV(x)==null?XF.unk:pphV(x)>=+XF.minpph))&&(!XF.country||M[x.manufacturer_id]?.country==XF.country)&&(!XF.type||x.type_id==XF.type)&&(!q||x.model.toLowerCase().includes(q)))
 .sort((a,b)=>(M[a.manufacturer_id]?.short||"").localeCompare(M[b.manufacturer_id]?.short||"")||a.model.localeCompare(b.model));
 const unkN=L.filter(x=>(XF.maxh&&x.min_height_cm==null)||(XF.minpph&&pphV(x)==null)).length;const estN=XF.minpph?L.filter(x=>x.capacity_pph==null&&x.pph_est!=null&&!x.pph_per_vehicle).length:0;let oth="";if(XF.type){const o={};DB.models.filter(x=>x.type_id==XF.type&&x.e3_category!=cat).forEach(x=>o[x.e3_category]=(o[x.e3_category]||0)+1);const k=Object.keys(o);if(k.length)oth=` · ещё ${Object.values(o).reduce((a,b)=>a+b,0)} ${plM(Object.values(o).reduce((a,b)=>a+b,0))} этого типа в других категориях: `+k.map(c=>MECH.includes(c)?`<a href="#/mech/${encodeURIComponent(c)}">${esc(c)}</a> (${o[c]})`:`${esc(c)} (${o[c]})`).join(", ")}
 $("#xcount").innerHTML=`показано ${L.length} из ${DB.models.filter(x=>x.e3_category==cat).length}`+(unkN?`, из них ${unkN} с неизвестным ростом или чел/час`:"")+(estN?`, у ${estN} чел/час — оценка книги`:"")+oth;$("#xgrid").innerHTML=L.map(mcard).join("")||'<p class="muted">Под фильтр ничего не подходит. <button class="btn" onclick="resetXF()">Сбросить фильтры</button></p>'}
P["compare"]=()=>{if(!CMP.length)return `<h1>Сравнение моделей</h1><p class="lead">Отметьте «сравнить» у 2–6 моделей в разделах с карточками: <a href="#/mech">«Механические»</a>, <a href="#/coasters">«Горки»</a>, <a href="#/wheels">«Колёса»</a>, <a href="#/water">«Водные»</a>, <a href="#/media">«Медиа»</a>, <a href="#/fec">«Центры»</a>, <a href="#/transport">«Поезда»</a> или <a href="#/kids">«Детские»</a>.</p>`;
 const L=CMP.map(id=>MD[id]);const F=[["Производитель",x=>M[x.manufacturer_id]?.short],["Страна",x=>M[x.manufacturer_id]?.country],["Статус для РФ",x=>rfBadge(M[x.manufacturer_id]?.rf_status),1],["Категория",x=>x.e3_category],["Назначение",x=>x.audience],["Места, шт",x=>x.seats],["Загрузка, чел/час",x=>pphF(x)],["Рост от, см",x=>hFull(x)],["Мощность, кВт",x=>x.power_kw],["Площадь, м²",x=>x.area_m2],["Габариты, м",x=>x.dimensions_m],["Высота, м",x=>x.height_m],["Длина трассы, м",x=>x.track_length_m],["Скорость, км/ч",x=>x.max_speed_kmh],["Переворотов",x=>x.inversions],["Диаметр колеса, м",x=>x.diameter_m],["Кабин",x=>x.gondolas],["Бесфундаментный",x=>x.foundation_free==null?null:(x.foundation_free?"да":"нет")],["Условия параметров и статус",x=>[x.param_notes,x.model_status?"Статус модели: "+x.model_status:"",x.mfr_warning].filter(Boolean).map(t=>"<p class=\"small\">"+esc(t)+"</p>").join("")||"<span class=\"muted\">Дополнительные условия не указаны; уточнить комплектацию у поставщика.</span>",1],["Преимущества и отличия",x=>advantagesCompact(x),1],["Основной источник модели",x=>srcLink(x.spec_source),1]];
 return `<h1>Сравнение моделей</h1><p class="small muted">Проверьте условия параметров и статус: числа могут относиться к типовой конфигурации или границе диапазона. Нажмите название модели, чтобы открыть полную карточку.</p><p><button class="btn" onclick="CMP=[];saveCMP();route(true)">Очистить</button></p><div class="tw"><table class="t"><tr><th></th>${L.map(x=>`<th><button class="btn compare-model" data-model="${esc(x.id)}" onclick="openModel('${x.id}')">${esc(x.model)}</button><br><button class="btn" onclick="toggleCMP('${x.id}')">убрать</button></th>`).join("")}</tr>
 ${F.map(f=>`<tr><td><b>${f[0]}</b></td>${L.map(x=>{const v=f[1](x);return `<td>${f[2]?v:(v==null||v===""?'<span class="muted">неизвестно</span>':fmt(v))}</td>`}).join("")}</tr>`).join("")}</table></div><p class="small muted">Чел/час: число — по источнику; «≈» — оценка книги (источник цифру не даёт): у механики «места × 20», у горок и колёс — по медиане книги для своего типа (см. «Методику»); «/ваг.» и «/маш.» — оценка на один вагон или машину, в сравнение и выгрузку не идёт; «*» — в рабочем каталоге считается формулой «места × 5», это ниже оценки книги (у механики — в 4 раза). Сравнивать загрузку и окупаемость можно только на одной базе.</p>`};
/* Questions are derived from missing or provisional inputs, not a score. */
function candidateQuestions(x){const m=M[x.manufacturer_id]||{};const q=[];q.push("Подтвердить выбранные преимущества на сопоставимой комплектации и условиях работы");
 const lead=x.lead||{};
 if(lead.kind!=="source"||lead.duration_kind!=="manufacturing")q.push(lead.kind==="approx"?"Подтвердить срок этой модели: в книге только ориентир":"Получить срок изготовления и отдельно доставки/монтажа");
 else q.push("Подтвердить актуальность срока и точку начала отсчета в новом КП");
 if(lead.day_basis)q.push("Уточнить календарный график: источник дает срок в днях, без универсального перевода в месяцы");
 if(x.capacity_pph==null||x.pph_est!=null||/формул|оценк/.test(x.pph_src||""))q.push("Получить рабочую пропускную способность и время цикла с посадкой");
 if(!m.service_rf)q.push("Уточнить сервис, запасные части и сроки их поставки");
 if(m.rf_status!=="поставляет")q.push("Подтвердить возможность поставки и ее условия");
 if(m.rf_operating_limitation)q.push(m.rf_operating_limitation);
 if(!x.installations||!x.installations.length)q.push("Запросить действующую установку этой версии для референс-визита");
 else q.push("Подтвердить действующий статус и совпадение версии у выбранного референсного объекта");
 return q;}
function candidateQuestionsHtml(L){return `<h2>Что уточнить по кандидатам</h2><p class="small muted">Эти вопросы помогают подготовить запрос. Они не являются рейтингом моделей; готовый лист "Запрос КП" входит в XLSX.</p><div class="scroll"><table><thead><tr><th>Модель</th><th>До включения в проект</th></tr></thead><tbody>${L.map(x=>`<tr><td><button class="btn" onclick="openModel('${esc(x.id)}')">${esc(x.model)}</button></td><td><ul>${candidateQuestions(x).map(q=>`<li>${esc(q)}</li>`).join("")}</ul></td></tr>`).join("")}</tbody></table></div>`;}
/* ---------- лонг-лист и выгрузка ---------- */
P["longlist"]=()=>{const L=LL.map(id=>MD[id]);return `<h1>Лонг-лист</h1><p class="lead">Отобранные модели, основания выбора и вопросы поставщикам. XLSX открывается как самостоятельная таблица.</p>${L.length?`<p><button class="btn pri" onclick="exportXLSX()">Скачать XLSX</button> <button class="btn" onclick="exportCSV()">Скачать CSV</button> <button class="btn" onclick="window.EncyclopediaFeed.clearSaved('models');LL=[];saveLL();route(true)">Очистить</button></p><div class="tw"><table class="t"><tr><th>Модель</th><th>Производитель</th><th>Тип</th><th>Источник</th><th></th></tr>${L.map(x=>`<tr><td><a href="javascript:openModel('${x.id}')">${esc(x.model)}</a></td><td>${mname(x.manufacturer_id)}</td><td>${esc(TY[x.type_id]?.name_ru||x.type_id)}</td><td>${srcLink(x.spec_source)}</td><td><button class="btn" onclick="toggleLL('${x.id}')">убрать</button></td></tr>`).join('')}</table></div>${candidateQuestionsHtml(L)}`:'<p>Пока пусто. Отметьте модели кнопкой + лонг-лист.</p>'}<h2>Как использовать выгрузку</h2><ol>${DB.paste_steps.map(s=>'<li>'+esc(s)+'</li>').join('')}</ol>`};
function pphV(x){return x.capacity_pph!=null?x.capacity_pph:(x.pph_est!=null&&!x.pph_per_vehicle?x.pph_est:null)}
function plN(n,a,b,c){const x=n%10,y=n%100;return x==1&&y!=11?a:x>=2&&x<=4&&(y<12||y>14)?b:c}
function plM(n){const a=n%10,b=n%100;return a==1&&b!=11?"модель":a>=2&&a<=4&&(b<12||b>14)?"модели":"моделей"}
