function pasteSteps(n){const N=n||0;return DB.paste_steps.map(s=>s.replace(/\{LAST\}/g,N?130+N:"130+N").replace(/\{N1\}/g,N?N+1:"N+1").replace(/\{N\}/g,N||"N"))}
